import React, { useState, useEffect } from "react";
import { ShieldCheck, Lock, User, ArrowRight, Zap, Cpu } from "lucide-react";

// Added { onLogin } prop here
const WorkerAuth = ({ onLogin }) => {
  const [loadingStage, setLoadingStage] = useState(0);
  const [showLogin, setShowLogin] = useState(false);

  // 10-Second Boot Sequence
  useEffect(() => {
    const intervals = [2000, 4500, 7000, 9000]; 
    const timers = intervals.map((ms, index) => {
      return setTimeout(() => setLoadingStage(index + 1), ms);
    });

    const finalTimer = setTimeout(() => setShowLogin(true), 10000);

    return () => {
      timers.forEach(clearTimeout);
      clearTimeout(finalTimer);
    };
  }, []);

  const bootMessages = [
    "INITIALIZING_NEURAL_LINK...",
    "SYNCING_COLLECTION_ROUTES...",
    "VERIFYING_ADMIN_PROTOCOLS...",
    "SYSTEM_READY_FOR_DEPLOYMENT"
  ];

  if (!showLogin) {
    return (
      <div className="h-screen w-full bg-[#47510B] flex flex-col items-center justify-center p-6 overflow-hidden">
        <div className="absolute inset-0 opacity-10 pointer-events-none" 
             style={{ backgroundImage: `linear-gradient(#CAD23C 1px, transparent 1px), linear-gradient(90deg, #CAD23C 1px, transparent 1px)`, backgroundSize: '40px 40px' }} />

        <div className="relative flex flex-col items-center">
          <div className="w-32 h-32 border-4 border-[#CAD23C] rounded-full flex items-center justify-center animate-pulse mb-8 relative">
            <Cpu size={48} className="text-[#CAD23C]" />
            <div className="absolute inset-0 border-t-4 border-[#FDFAD8] rounded-full animate-spin" />
          </div>

          <h1 className="text-[#CAD23C] font-black text-4xl italic tracking-tighter uppercase mb-2">
            T2T_WORKER
          </h1>

          <div className="flex items-center gap-3">
             <div className="h-[2px] w-12 bg-[#CAD23C]/30" />
             <span className="text-[10px] font-black text-[#FDFAD8] tracking-[0.5em] uppercase">
                {bootMessages[loadingStage] || "CONNECTING..."}
             </span>
             <div className="h-[2px] w-12 bg-[#CAD23C]/30" />
          </div>

          <div className="mt-10 w-64 h-1 bg-black/20 rounded-full overflow-hidden">
            <div 
              className="h-full bg-[#CAD23C] transition-all duration-1000 ease-out shadow-[0_0_15px_#CAD23C]" 
              style={{ width: `${(loadingStage + 1) * 25}%` }} 
            />
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen w-full bg-[#FDFAD8] flex items-center justify-center p-6 animate-slide-up">
      <div className="w-full max-w-[420px] bg-white border-4 border-[#47510B] rounded-[50px] shadow-[0_25px_0_0_#47510B] p-10 relative overflow-hidden">

        <div className="absolute top-0 right-0 p-6 opacity-10 rotate-12">
            <ShieldCheck size={120} strokeWidth={1} />
        </div>

        <div className="relative z-10">
          <div className="flex items-center gap-2 mb-8">
            <span className="w-3 h-3 bg-[#AB1717] rounded-full animate-pulse" />
            <span className="text-xs font-black text-[#47510B] uppercase tracking-widest">Authorized Personnel Only</span>
          </div>

          <h2 className="text-5xl font-black text-[#47510B] uppercase tracking-tighter leading-none mb-10">
            WORKER<br/><span className="text-[#CAD23C] stroke-black drop-shadow-sm">STATION</span>
          </h2>

          <div className="space-y-6">
            <div className="relative">
              <label className="text-[10px] font-black text-[#47510B]/50 uppercase ml-2 mb-2 block">Operator_ID</label>
              <div className="relative">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 text-[#47510B]/30" size={20} />
                <input type="text" placeholder="ID_7729_X" className="w-full bg-[#FDFAD8]/50 border-2 border-[#47510B] p-5 pl-14 rounded-3xl font-bold outline-none focus:ring-4 ring-[#CAD23C] transition-all" />
              </div>
            </div>

            <div className="relative">
              <label className="text-[10px] font-black text-[#47510B]/50 uppercase ml-2 mb-2 block">Secure_Key</label>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-[#47510B]/30" size={20} />
                <input type="password" placeholder="••••••••" className="w-full bg-[#FDFAD8]/50 border-2 border-[#47510B] p-5 pl-14 rounded-3xl font-bold outline-none focus:ring-4 ring-[#CAD23C] transition-all" />
              </div>
            </div>

            {/* Added onClick={onLogin} here */}
            <button 
              onClick={onLogin}
              className="w-full bg-[#47510B] text-[#CAD23C] font-black py-6 rounded-3xl flex items-center justify-center gap-4 shadow-[0_8px_0_0_#2A3106] active:translate-y-1 active:shadow-none transition-all uppercase text-2xl italic group"
            >
              Login to System <ArrowRight className="group-hover:translate-x-2 transition-transform" size={28} />
            </button>
          </div>

          <div className="mt-10 flex justify-between items-center opacity-40">
            <div className="flex items-center gap-2">
                <Zap size={14} />
                <span className="text-[10px] font-black tracking-widest">ENCRYPTED_NODE</span>
            </div>
            <span className="text-[10px] font-black italic">v2.0.4</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default WorkerAuth;
